package vn.edu.crs.courseservice.config;
import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import vn.edu.crs.courseservice.security.JwtAuthFilter;
@Configuration @RequiredArgsConstructor public class SecurityConfig {private final JwtAuthFilter jwt; @Bean SecurityFilterChain filterChain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((request,response,error)->response.sendError(401))).authorizeHttpRequests(a->a.requestMatchers("/internal/**").permitAll().requestMatchers(HttpMethod.GET,"/courses/**").permitAll().requestMatchers(HttpMethod.POST,"/courses/**").hasRole("ADMIN").requestMatchers(HttpMethod.PUT,"/courses/**").hasRole("ADMIN").requestMatchers(HttpMethod.DELETE,"/courses/**").hasRole("ADMIN").anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}}
